args.command:
$testScript = @"
Write-Host 'Start'
Measure-Command {
    `$env:POWERSHELL_TELEMETRY_OPTOUT = `"1`"
    `$env:EDITOR = `"nvim`"
    `$env:PAGER  = `"less`"
    `$ErrorActionPreference = `"SilentlyContinue`"
    `$ProgressPreference = `"SilentlyContinue`"
} | Select-Object TotalMilliseconds | Write-Host -ForegroundColor Cyan

Write-Host 'OMP'
Measure-Command {
    if (Get-Command oh-my-posh -ErrorAction Ignore) {
        `$ompCache = Join-Path `$env:TEMP `"omp-init.ps1`"
        if (Test-Path `$ompCache) {
            . `$ompCache
        }
    }
} | Select-Object TotalMilliseconds | Write-Host -ForegroundColor Cyan

Write-Host 'Forgum'
Measure-Command {
    if (Get-Module Forgum -ListAvailable) {
        Invoke-Forgum -Lolcat
    }
} | Select-Object TotalMilliseconds | Write-Host -ForegroundColor Cyan

Write-Host 'Zoxide'
Measure-Command {
    if (Get-Command zoxide -ErrorAction Ignore) {
        zoxide init powershell | Out-String | Invoke-Expression
    }
} | Select-Object TotalMilliseconds | Write-Host -ForegroundColor Cyan
"@

$testScript | Out-File $env:TEMP\profile-perf.ps1
pwsh -NoProfile -File $env:TEMP\profile-perf.ps1

$profileContent = Get-Content $PROFILE -Raw
$newProfile = @"
# [1] Early Environment (Fast)
`$env:POWERSHELL_TELEMETRY_OPTOUT = "1"
`$env:EDITOR = "nvim"
`$env:PAGER  = "less"
`$ErrorActionPreference = "SilentlyContinue"
`$ProgressPreference = "SilentlyContinue"
`$global:PSProfileLoadTime = `$null

# [2] Optimized Prompt (Static OMP)
if (Get-Command oh-my-posh -ErrorAction Ignore) {
    `$ompCache = Join-Path `$env:TEMP "omp-init.ps1"
    if (Test-Path `$ompCache) {
        . `$ompCache
    } else {
        oh-my-posh init pwsh --config "`$env:POSH_THEMES_PATH/tokyo.omp.json" | Out-File -FilePath `$ompCache -Encoding utf8
        . `$ompCache
    }
}

# [3] Fast Forgum (Deferred/Background)
# Rather than blocking the startup thread for 2-3 seconds importing Forgum,
# we start a fast background job to render the cow and fortune, then display it when ready.
`$env:COLORTERM = 'truecolor'
`$forgumJob = Start-Job -ScriptBlock {
    Import-Module Forgum -DisableNameChecking
    Invoke-Forgum -Lolcat
}
Register-EngineEvent -SourceIdentifier ([System.Management.Automation.PsEngineEvent]::Exiting) -Action { Remove-Job -State Completed -Force } | Out-Null
Register-ObjectEvent -InputObject `$forgumJob -EventName StateChanged -Action {
    if (`$Sender.State -eq 'Completed') {
        Receive-Job `$Sender | Write-Host
        Remove-Job `$Sender
    }
} | Out-Null

# [4] Dynamic Module Loading
function ls {
    if (-not (Get-Module Terminal-Icons -ErrorAction Ignore)) { Import-Module Terminal-Icons }
    Get-ChildItem -Force @args | Sort-Object @{Expression={`$_.PSIsContainer};Descending=`$true}, Name
}
function gs {
    if (-not (Get-Module posh-git -ErrorAction Ignore)) { Import-Module posh-git }
    git status @args
}

# [5] Essential Aliases & Helpers
Set-Alias grep Select-String
Set-Alias cat bat
Set-Alias vim nvim
if (Get-Command zoxide -ErrorAction Ignore) {
    zoxide init powershell | Out-String | Invoke-Expression
}
"@
$newProfile | Out-File $PROFILE -Encoding utf8
Measure-Command { pwsh -NoProfile -Command ". '$PROFILE'" }

$testScript = @"
Write-Host 'Start'
Measure-Command {
    `$env:POWERSHELL_TELEMETRY_OPTOUT = `"1`"
    `$env:EDITOR = `"nvim`"
